//! Bounded pre-QC replay inputs for the governed asynchronous profile.
//! Worlds are regenerated by native execution, never duplicated here. Canonical
//! CandidateStore remains immutable by height and receives only QC-selected work.
#![cfg_attr(not(test), allow(dead_code))] // Execution owner wiring is in progress.
#[cfg(feature = "qualification-timing")]
use crate::services::qualification_timing::{
    processing_span as diagnostic_span, ProcessingStage as DiagnosticStage,
};

use super::{authority::VerifiedAuthority, ingress::ProcessingBuildRequest};
use serde::{Deserialize, Serialize};
use std::{
    collections::BTreeSet,
    path::{Path, PathBuf},
    sync::Arc,
};
use synergy_etdag::{
    execution::{CandidateProtectedMaterial, ProcessingOrderGroup},
    EtdagDigest,
};
use synergy_execution::{BudgetedExecutionCandidate, ProcessingReadyRecord};
use synergy_posy::{ConsensusObjectContext, SimplifiedFinalityParent};
use synergy_state::world_resources::{WorldResourceBudget, WorldResourcePermit};
use synergy_storage::{AtomicStore, RequiredRecord, StoragePrecondition, StorageTransaction};

const SLOTS: usize = 32;
const MAX_BYTES: usize = 8 * 1024 * 1024;
const MAX_MANIFEST_BYTES: usize = 16 * 1024;
const HEADER: &str = "proposal-inputs-v1.json";

#[derive(Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
struct Header {
    version: u32,
    namespace: EtdagDigest,
    generation: u64,
}

#[derive(Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct ProcessingProposalInputs {
    pub context: ConsensusObjectContext,
    pub parent: SimplifiedFinalityParent,
    pub takeover_id: Option<String>,
    pub block_id: String,
    pub state_root: String,
    pub protected_execution_root: String,
    pub ordered_group: Option<ProcessingOrderGroup>,
    pub publications: Vec<ProcessingReadyRecord>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub certified_ancestors: Vec<(synergy_posy::SimplifiedQuorumCertificate, String)>,
}
#[derive(Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct Record {
    version: u32,
    namespace: EtdagDigest,
    inputs: ProcessingProposalInputs,
}
#[derive(Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct CertifiedArchive {
    version: u32,
    namespace: EtdagDigest,
    inputs: ProcessingProposalInputs,
    validation: synergy_posy::ProposalValidationCertificate,
    qc: synergy_posy::SimplifiedQuorumCertificate,
}
#[derive(Serialize)]
struct CertifiedArchiveRef<'a> {
    version: u32,
    namespace: &'a EtdagDigest,
    inputs: &'a ProcessingProposalInputs,
    validation: &'a synergy_posy::ProposalValidationCertificate,
    qc: &'a synergy_posy::SimplifiedQuorumCertificate,
}
struct ChargedArchive {
    record: CertifiedArchive,
    _permit: WorldResourcePermit,
}
#[derive(Debug)]
pub(crate) enum ProcessingProposalError {
    Capacity(synergy_state::world_resources::WorldResourceError),
    AwaitingValidation,
    StagingFull,
    Invalid(String),
}
impl ProcessingProposalError {
    pub(super) fn is_capacity(&self) -> bool {
        matches!(self, Self::Capacity(_))
    }
    pub(super) fn is_retryable(&self) -> bool {
        matches!(
            self,
            Self::Capacity(_) | Self::AwaitingValidation | Self::StagingFull
        )
    }
}
impl From<synergy_state::world_resources::WorldResourceError> for ProcessingProposalError {
    fn from(error: synergy_state::world_resources::WorldResourceError) -> Self {
        match error {
            synergy_state::world_resources::WorldResourceError::Capacity { .. } => {
                Self::Capacity(error)
            }
            error => Self::Invalid(error.to_string()),
        }
    }
}
impl From<String> for ProcessingProposalError {
    fn from(error: String) -> Self {
        Self::Invalid(error)
    }
}
impl From<&str> for ProcessingProposalError {
    fn from(error: &str) -> Self {
        Self::Invalid(error.into())
    }
}
impl std::fmt::Display for ProcessingProposalError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Capacity(error) => std::fmt::Display::fmt(error, f),
            Self::Invalid(error) => f.write_str(error),
            Self::AwaitingValidation => f.write_str("processing candidate awaits durable VC"),
            Self::StagingFull => f.write_str("processing proposal staging is full"),
        }
    }
}
const MAX_ARCHIVE_PINS: usize = 4 * 4096 + 64;
const ARCHIVE_PRUNE_BATCH: usize = 4;
fn archive_path(height: u64) -> String {
    format!("certified/{height:020}.json")
}
fn archive_id_path(id: &str) -> String {
    format!("certified-ids/{id}.json")
}
fn archive_group_path(id: &EtdagDigest) -> String {
    format!("certified-groups/{}.json", id.0)
}
struct Index {
    block_id: String,
    height: u64,
    root: EtdagDigest,
    bytes: usize,
    validation: Option<(EtdagDigest, usize)>,
}

/// The private durable token is returned only after a successful native store
/// transaction. A World or an arbitrary deserialized flag cannot construct it.
pub(crate) struct DurableProcessingCandidate {
    request: Arc<ProcessingBuildRequest>,
    candidate: Arc<BudgetedExecutionCandidate>,
}
impl DurableProcessingCandidate {
    pub(super) fn into_parts(
        self,
    ) -> (Arc<ProcessingBuildRequest>, Arc<BudgetedExecutionCandidate>) {
        (self.request, self.candidate)
    }
}
pub(super) struct ChargedInputs {
    inputs: ProcessingProposalInputs,
    _permit: WorldResourcePermit,
}
impl std::ops::Deref for ChargedInputs {
    type Target = ProcessingProposalInputs;
    fn deref(&self) -> &Self::Target {
        &self.inputs
    }
}

pub(crate) trait ProcessingProposalRetirement {
    /// Require durable QC-selected canonical material or verified abandonment,
    /// AND absence of pending reveal/recovery references to this exact block.
    fn verify_retirement(&self, height: u64, block_id: &str) -> Result<(), String>;
}
pub(crate) struct ProcessingProposalStore {
    store: AtomicStore,
    header: Header,
    entries: Vec<Option<Index>>,
    budget: Arc<WorldResourceBudget>,
    authority: Arc<VerifiedAuthority>,
    _scratch: WorldResourcePermit,
}
fn path(slot: usize) -> String {
    format!("inputs/{slot:02}.json")
}
fn validation_path(slot: usize) -> String {
    format!("validations/{slot:02}.json")
}
fn root(bytes: &[u8]) -> EtdagDigest {
    EtdagDigest::from_domain_bytes("SYNERGY_POSY_PROCESSING_DURABLE_INPUTS_V1", bytes)
}
fn encode(value: &impl Serialize) -> Result<Vec<u8>, String> {
    serde_json::to_vec(value).map_err(|e| e.to_string())
}
fn charge(bytes: usize) -> Result<usize, String> {
    bytes
        .checked_mul(32)
        .and_then(|n| n.checked_add(64 * 1024))
        .ok_or_else(|| "processing input size overflow".into())
}
fn check(record: &Record, namespace: &EtdagDigest) -> Result<(), String> {
    if record.version != 1 || &record.namespace != namespace {
        return Err("invalid durable processing proposal scope/shape".into());
    }
    check_inputs(&record.inputs, namespace)
}
fn check_inputs(inputs: &ProcessingProposalInputs, namespace: &EtdagDigest) -> Result<(), String> {
    if inputs.context.height == 0
        || inputs.parent.height().checked_add(1) != Some(inputs.context.height)
        || !synergy_posy::is_hash(&inputs.block_id)
        || !synergy_posy::is_hash(&inputs.state_root)
        || !synergy_posy::is_hash(&inputs.protected_execution_root)
        || (inputs.context.round == 0) != inputs.takeover_id.is_none()
        || inputs.publications.len() > 4096
    {
        return Err("invalid durable processing proposal scope/shape".into());
    }
    if let Some(group) = &inputs.ordered_group {
        group
            .commitment()
            .map_err(|e| format!("processing proposal group: {e:?}"))?;
        if &group.namespace_root != namespace {
            return Err("processing proposal group namespace differs".into());
        }
    }
    Ok(())
}
/// Keep the original epoch-one archive intact. Every successor opens a
/// separate deterministic store whose header still enforces its signed namespace.
pub(super) fn epoch_store_path(blocks: &Path, epoch: u64) -> std::path::PathBuf {
    if epoch == 1 {
        blocks.join("processing-proposal-inputs-v1")
    } else {
        blocks.join(format!("processing-proposal-inputs-v1-epoch-{epoch:020}"))
    }
}

impl ProcessingProposalStore {
    pub(crate) fn open(
        root_path: &Path,
        namespace: EtdagDigest,
        budget: &Arc<WorldResourceBudget>,
        authority: Arc<VerifiedAuthority>,
    ) -> Result<Self, String> {
        namespace
            .validate()
            .map_err(|e| format!("processing proposal namespace: {e:?}"))?;
        if namespace.is_zero()
            || !authority.processing_profile_enabled()
            || namespace != super::processing_pipeline::processing_namespace(&authority, budget)?
        {
            return Err("processing proposal namespace differs from signed profile".into());
        }
        // Covers bounded transaction recovery before a slot can be identified.
        let scratch = budget
            .reserve(2 * MAX_BYTES + 8 * MAX_MANIFEST_BYTES + SLOTS * 1024)
            .map_err(|e| e.to_string())?;
        let mut store =
            AtomicStore::new_with_manifest_limit(root_path, MAX_BYTES, MAX_MANIFEST_BYTES)
                .map_err(|e| e.to_string())?;
        if !store.exists(HEADER).map_err(|e| e.to_string())? {
            for directory in ["certified", "certified-ids", "certified-groups"] {
                match std::fs::symlink_metadata(root_path.join(directory)) {
                    Ok(_) => {
                        return Err("certified processing history exists without header".into())
                    }
                    Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
                    Err(error) => return Err(error.to_string()),
                }
            }
            store
                .inspect_consistent(|reader| -> Result<(), String> {
                    for slot in 0..SLOTS {
                        if reader
                            .optional_record_bytes(path(slot))
                            .map_err(|e| e.to_string())?
                            .is_some()
                            || reader
                                .optional_record_bytes(validation_path(slot))
                                .map_err(|e| e.to_string())?
                                .is_some()
                        {
                            return Err("processing inputs exist without header".into());
                        }
                    }
                    Ok(())
                })
                .map_err(|e| e.to_string())??;
            let header = Header {
                version: 1,
                namespace: namespace.clone(),
                generation: 0,
            };
            let mut transaction = StorageTransaction::new(4096).map_err(|e| e.to_string())?;
            transaction
                .put(HEADER, encode(&header)?)
                .map_err(|e| e.to_string())?;
            transaction
                .commit_guarded(
                    &mut store,
                    &[StoragePrecondition {
                        relative_path: HEADER.into(),
                        required: RequiredRecord::MissingOrSameWrite,
                    }],
                )
                .map_err(|e| e.to_string())?;
        }
        let (header, entries) = store
            .inspect_consistent(|reader| -> Result<_, String> {
                let bytes = reader
                    .with_maximum_bytes(4096)
                    .read_optional_bounded(HEADER)
                    .map_err(|e| e.to_string())?
                    .ok_or("missing processing proposal header")?;
                let header: Header = serde_json::from_slice(&bytes).map_err(|e| e.to_string())?;
                if header.version != 1 || header.namespace != namespace {
                    return Err("processing proposal authority mismatch".into());
                }
                let mut entries: Vec<Option<Index>> = (0..SLOTS).map(|_| None).collect();
                for slot in 0..SLOTS {
                    let Some(size) = reader
                        .optional_record_bytes(path(slot))
                        .map_err(|e| e.to_string())?
                    else {
                        if reader
                            .optional_record_bytes(validation_path(slot))
                            .map_err(|e| e.to_string())?
                            .is_some()
                        {
                            return Err("processing VC exists without replay inputs".into());
                        }
                        continue;
                    };
                    if size == 0 || size > MAX_BYTES {
                        return Err("processing proposal record exceeds bound".into());
                    }
                    let _decode = budget.reserve(charge(size)?).map_err(|e| e.to_string())?;
                    let bytes = reader
                        .read_optional_bounded(path(slot))
                        .map_err(|e| e.to_string())?
                        .ok_or("processing proposal record disappeared")?;
                    if bytes == b"null" {
                        if let Some(validation) = reader
                            .read_optional_bounded(validation_path(slot))
                            .map_err(|e| e.to_string())?
                        {
                            if validation != b"null" {
                                return Err("processing VC exists for retired inputs".into());
                            }
                        }
                        continue;
                    }
                    let record: Record =
                        serde_json::from_slice(&bytes).map_err(|e| e.to_string())?;
                    check(&record, &namespace)?;
                    if entries
                        .iter()
                        .flatten()
                        .any(|entry| entry.block_id == record.inputs.block_id)
                    {
                        return Err("duplicate durable processing candidate".into());
                    }
                    record
                        .inputs
                        .context
                        .validate_against(&authority.epoch)
                        .map_err(|e| e.to_string())?;
                    let validation = match reader
                        .optional_record_bytes(validation_path(slot))
                        .map_err(|e| e.to_string())?
                    {
                        None => None,
                        Some(size) => {
                            if size == 0 || size > MAX_BYTES {
                                return Err("processing VC exceeds bound".into());
                            }
                            let _decode_vc =
                                budget.reserve(charge(size)?).map_err(|e| e.to_string())?;
                            let vc_bytes = reader
                                .read_optional_bounded(validation_path(slot))
                                .map_err(|e| e.to_string())?
                                .ok_or("missing processing VC")?;
                            if vc_bytes == b"null" {
                                None
                            } else {
                                let vc: synergy_posy::ProposalValidationCertificate =
                                    serde_json::from_slice(&vc_bytes).map_err(|e| e.to_string())?;
                                verify_validation(&record.inputs, &vc, &authority)?;
                                Some((root(&vc_bytes), size))
                            }
                        }
                    };
                    entries[slot] = Some(Index {
                        block_id: record.inputs.block_id,
                        height: record.inputs.context.height,
                        root: root(&bytes),
                        bytes: size,
                        validation,
                    });
                }
                Ok((header, entries))
            })
            .map_err(|e| e.to_string())??;
        let mut opened = Self {
            store,
            header,
            entries,
            budget: Arc::clone(budget),
            authority,
            _scratch: scratch,
        };
        // A crash may occur after certified archival but before reusable-slot
        // clearing. Resume only these at-most-32 exact heights; never scan history.
        let heights = opened
            .entries
            .iter()
            .flatten()
            .map(|entry| entry.height)
            .collect::<BTreeSet<_>>();
        for height in heights {
            if let Some(archive) = opened.read_archive_at(height)? {
                opened.compact_certified_stage(&archive.record.qc, &BTreeSet::new())?;
            }
        }
        Ok(opened)
    }

    /// Upgrade legacy certified imports without scanning history or evicting
    /// speculative material. Missing/mismatched QC authority leaves a slot intact.
    pub(super) fn recover_certified_stages(
        &mut self,
        qcs: &synergy_posy::VerifiedQuorumCertificateStore,
    ) -> Result<(), String> {
        let staged = self
            .entries
            .iter()
            .flatten()
            .map(|entry| (entry.height, entry.block_id.clone()))
            .collect::<Vec<_>>();
        for (height, block_id) in staged {
            let Some(qc) = qcs
                .get_verified(
                    height,
                    &self.authority.epoch,
                    &self.authority.registry,
                    self.authority.as_ref(),
                )
                .map_err(|error| error.to_string())?
            else {
                continue;
            };
            if qc.block_id != block_id || !self.has_validation(&block_id) {
                continue;
            }
            let (bytes, _permit) = self.export_sync(&block_id)?;
            self.try_import_certified(&bytes, &qc)
                .map_err(|error| error.to_string())?;
            // Exact certified archive now owns the unchanged replay inputs/VC.
            self.compact_certified_stage(&qc, &BTreeSet::new())?;
        }
        Ok(())
    }

    fn read_archive_at(&self, height: u64) -> Result<Option<ChargedArchive>, String> {
        self.try_read_archive_at(height)
            .map_err(|error| error.to_string())
    }
    fn try_read_archive_at(
        &self,
        height: u64,
    ) -> Result<Option<ChargedArchive>, ProcessingProposalError> {
        self.store
            .inspect_consistent(|reader| -> Result<_, ProcessingProposalError> {
                let Some(size) = reader
                    .optional_record_bytes(archive_path(height))
                    .map_err(|error| ProcessingProposalError::Invalid(error.to_string()))?
                else {
                    return Ok(None);
                };
                if size == 0 || size > MAX_BYTES {
                    return Err(ProcessingProposalError::Invalid(
                        "certified processing archive exceeds bound".into(),
                    ));
                }
                let permit = self
                    .budget
                    .reserve(charge(size).map_err(ProcessingProposalError::Invalid)?)
                    .map_err(|error| match error {
                        synergy_state::world_resources::WorldResourceError::Capacity { .. } => {
                            ProcessingProposalError::Capacity(error)
                        }
                        error => ProcessingProposalError::Invalid(error.to_string()),
                    })?;
                let bytes = reader
                    .read_optional_bounded(archive_path(height))
                    .map_err(|error| ProcessingProposalError::Invalid(error.to_string()))?
                    .ok_or_else(|| {
                        ProcessingProposalError::Invalid(
                            "certified processing archive disappeared".into(),
                        )
                    })?;
                let record: CertifiedArchive = serde_json::from_slice(&bytes)
                    .map_err(|error| ProcessingProposalError::Invalid(error.to_string()))?;
                self.verify_archive(&record, height)
                    .map_err(ProcessingProposalError::Invalid)?;
                Ok(Some(ChargedArchive {
                    record,
                    _permit: permit,
                }))
            })
            .map_err(|error| ProcessingProposalError::Invalid(error.to_string()))?
    }
    fn archive_locator(&self, path: String) -> Result<Option<u64>, String> {
        self.store
            .inspect_consistent(|reader| -> Result<_, String> {
                reader
                    .with_maximum_bytes(8)
                    .read_optional_bounded(path)
                    .map_err(|e| e.to_string())?
                    .map(|bytes| {
                        <[u8; 8]>::try_from(bytes)
                            .map(u64::from_be_bytes)
                            .map_err(|_| "invalid certified processing locator".to_string())
                    })
                    .transpose()
            })
            .map_err(|e| e.to_string())?
    }
    fn try_read_archive(
        &self,
        block_id: &str,
    ) -> Result<Option<ChargedArchive>, ProcessingProposalError> {
        if !synergy_posy::is_hash(block_id) {
            return Err("invalid certified processing block ID".into());
        }
        let Some(height) = self.archive_locator(archive_id_path(block_id))? else {
            return Ok(None);
        };
        let record = self
            .try_read_archive_at(height)?
            .ok_or("certified processing locator lacks archive")?;
        if record.record.inputs.block_id != block_id {
            return Err("certified processing locator differs from archive".into());
        }
        Ok(Some(record))
    }
    fn verify_archive(&self, record: &CertifiedArchive, height: u64) -> Result<(), String> {
        if record.version != 1
            || record.namespace != self.header.namespace
            || record.inputs.context.height != height
            || !record.inputs.certified_ancestors.is_empty()
        {
            return Err("certified processing archive scope mismatch".into());
        }
        check_inputs(&record.inputs, &self.header.namespace)?;
        record
            .inputs
            .context
            .validate_against(&self.authority.epoch)
            .map_err(|e| e.to_string())?;
        record
            .qc
            .verify(
                &self.authority.epoch,
                &self.authority.registry,
                self.authority.as_ref(),
            )
            .map_err(|e| e.to_string())?;
        verify_validation(&record.inputs, &record.validation, &self.authority)?;
        verify_certified_subject(&record.validation, &record.qc)?;
        if record.qc.context.height != height
            || record.qc.block_id != record.inputs.block_id
            || record.qc.parent != record.inputs.parent
            || record.qc.protected_execution_root != record.inputs.protected_execution_root
        {
            return Err("certified processing archive differs from native QC".into());
        }
        Ok(())
    }
    /// Move exact replay inputs and ECHO authority into height-addressed history
    /// only after native execution installed the QC-selected canonical candidate.
    /// No World is copied, and no archive is trusted without its native proofs.
    pub(super) fn archive_certified(
        &mut self,
        qc: &synergy_posy::SimplifiedQuorumCertificate,
        candidate: &BudgetedExecutionCandidate,
    ) -> Result<(), String> {
        self.try_archive_certified(qc, candidate)
            .map_err(|error| error.to_string())
    }
    pub(super) fn try_archive_certified(
        &mut self,
        qc: &synergy_posy::SimplifiedQuorumCertificate,
        candidate: &BudgetedExecutionCandidate,
    ) -> Result<(), ProcessingProposalError> {
        #[cfg(feature = "qualification-timing")]
        let _diagnostic = diagnostic_span(DiagnosticStage::ArchiveCertified);
        qc.verify(
            &self.authority.epoch,
            &self.authority.registry,
            self.authority.as_ref(),
        )
        .map_err(|e| e.to_string())?;
        candidate.validate()?;
        if candidate.height != qc.context.height
            || candidate.block_id != qc.block_id
            || candidate.parent_block_id != qc.parent_block_id
            || candidate.protected_execution_root != qc.protected_execution_root
        {
            return Err("processing archive candidate differs from native QC".into());
        }
        if let Some(old) = self.try_read_archive_at(candidate.height)? {
            if old.record.inputs.block_id != candidate.block_id
                || old.record.inputs.state_root != candidate.state_root
            {
                return Err("conflicting immutable certified processing archive".into());
            }
            return Ok(());
        }
        let inputs = self.try_load_inputs(&candidate.block_id)?;
        if inputs.state_root != candidate.state_root {
            return Err("processing archive differs from installed state".into());
        }
        let (bytes, _encode) = self.try_with_validation(&candidate.block_id, |vc| {
            verify_validation(&inputs, vc, &self.authority)?;
            verify_certified_subject(vc, qc)?;
            let value = CertifiedArchiveRef {
                version: 1,
                namespace: &self.header.namespace,
                inputs: &inputs,
                validation: vc,
                qc,
            };
            let mut size = SizeCounter(0);
            serde_json::to_writer(&mut size, &value).map_err(|e| e.to_string())?;
            let permit = self
                .budget
                .reserve(charge(size.0)?)
                .map_err(ProcessingProposalError::from)?;
            Ok((encode(&value)?, permit))
        })?;
        let mut writes = vec![
            (archive_path(candidate.height), bytes),
            (
                archive_id_path(&candidate.block_id),
                candidate.height.to_be_bytes().to_vec(),
            ),
        ];
        if let Some(group) = &inputs.ordered_group {
            writes.push((
                archive_group_path(&group.root().map_err(|e| format!("{e:?}"))?),
                candidate.height.to_be_bytes().to_vec(),
            ));
        }
        drop(inputs);
        self.replace_records(writes)
            .map_err(ProcessingProposalError::from)
    }
    /// The native QC excludes other candidates at this exact height. References
    /// to the selected candidate resolve to the verified durable archive first.
    pub(super) fn compact_certified_stage(
        &mut self,
        qc: &synergy_posy::SimplifiedQuorumCertificate,
        protected_block_ids: &BTreeSet<String>,
    ) -> Result<(), String> {
        self.try_compact_certified_stage(qc, protected_block_ids)
            .map_err(|error| error.to_string())
    }
    pub(super) fn try_compact_certified_stage(
        &mut self,
        qc: &synergy_posy::SimplifiedQuorumCertificate,
        protected_block_ids: &BTreeSet<String>,
    ) -> Result<(), ProcessingProposalError> {
        qc.verify(
            &self.authority.epoch,
            &self.authority.registry,
            self.authority.as_ref(),
        )
        .map_err(|e| e.to_string())?;
        let archive = self
            .try_read_archive_at(qc.context.height)?
            .ok_or("processing stage has no certified archive")?;
        if archive.record.inputs.block_id != qc.block_id {
            return Err("processing stage archive differs from native QC".into());
        }
        drop(archive);
        let slots = self
            .entries
            .iter()
            .enumerate()
            .filter_map(|(slot, entry)| {
                entry
                    .as_ref()
                    .filter(|entry| {
                        entry.height == qc.context.height
                            && (entry.block_id == qc.block_id
                                || !protected_block_ids.contains(&entry.block_id))
                    })
                    .map(|_| slot)
            })
            .collect::<Vec<_>>();
        for slot in slots {
            let entry = self.entries[slot].as_ref().expect("located stage");
            self.try_read(slot, entry)?;
            if entry.validation.is_some() {
                self.try_with_validation(&entry.block_id, |_| Ok(()))?;
            }
            self.replace_records(vec![
                (path(slot), b"null".to_vec()),
                (validation_path(slot), b"null".to_vec()),
            ])?;
            self.entries[slot] = None;
        }
        Ok(())
    }
    /// Bound both new-range work and revisiting released sparse pins. Pins are
    /// durable before the cursor advances; a crash repeats an exact finite range.
    pub(crate) fn prune_archive(
        &mut self,
        finalized: u64,
        retain: u64,
        protected_heights: &BTreeSet<u64>,
    ) -> Result<(), String> {
        let Some(through) = synergy_storage::PruneBoundary {
            finalized_height: finalized,
            retain_from_height: retain,
        }
        .oldest_prunable_height()
        .map_err(|e| e.to_string())?
        else {
            return Ok(());
        };
        if protected_heights.len() > MAX_ARCHIVE_PINS {
            return Err("too many processing archive pins".into());
        }
        let cursor_path = "certified/.pruned-through";
        let pins_path = "certified/.retained-heights";
        let previous = self.archive_locator(cursor_path.into())?.unwrap_or(0);
        let pin_bytes = self
            .store
            .inspect_consistent(|reader| reader.optional_record_bytes(pins_path))
            .map_err(|e| e.to_string())?
            .map_err(|e| e.to_string())?
            .unwrap_or(0);
        if pin_bytes > MAX_ARCHIVE_PINS * 8 {
            return Err("processing archive pin record exceeds bound".into());
        }
        // Preflight exact bytes before decoding the bounded sparse-pin index.
        let _metadata = match self.budget.reserve(pin_bytes * 32 + 16 * 1024) {
            Ok(permit) => permit,
            Err(synergy_state::world_resources::WorldResourceError::Capacity { .. }) => {
                return Ok(())
            }
            Err(error) => return Err(error.to_string()),
        };
        let mut retained = self
            .store
            .inspect_consistent(|reader| -> Result<BTreeSet<u64>, String> {
                let Some(bytes) = reader
                    .with_maximum_bytes(pin_bytes)
                    .read_optional_bounded(pins_path)
                    .map_err(|e| e.to_string())?
                else {
                    if previous != 0 {
                        return Err("processing archive cursor lacks sparse pin ledger".into());
                    }
                    return Ok(BTreeSet::new());
                };
                if bytes.len() % 8 != 0 {
                    return Err("invalid processing archive pin record".into());
                }
                let mut result = BTreeSet::new();
                for value in bytes.chunks_exact(8) {
                    let h = u64::from_be_bytes(value.try_into().expect("eight byte chunk"));
                    if h == 0 || h > previous || !result.insert(h) {
                        return Err("invalid processing archive pin height".into());
                    }
                }
                Ok(result)
            })
            .map_err(|e| e.to_string())??;
        let released = retained
            .iter()
            .filter(|h| **h <= through && !protected_heights.contains(h))
            .take(ARCHIVE_PRUNE_BATCH)
            .copied()
            .collect::<Vec<_>>();
        let remaining = ARCHIVE_PRUNE_BATCH - released.len();
        let end = previous
            .saturating_add(remaining as u64)
            .min(through)
            .max(previous);
        // A caught-up cursor with no released pin has no durable transition.
        // Rewriting its identical metadata on every owner poll otherwise holds
        // the shared proposal lock across an unnecessary guarded transaction.
        if end == previous && released.is_empty() {
            return Ok(());
        }
        let mut remove = released.clone();
        for h in previous.saturating_add(1)..=end {
            if protected_heights.contains(&h) {
                retained.insert(h);
            } else {
                remove.push(h);
            }
        }
        for h in &released {
            retained.remove(h);
        }
        if retained.len() > MAX_ARCHIVE_PINS {
            return Err("processing archive pin index full".into());
        }
        let mut paths = Vec::<PathBuf>::new();
        for h in remove {
            let archive = match self.try_read_archive_at(h) {
                Ok(archive) => archive,
                Err(ProcessingProposalError::Capacity(_)) => return Ok(()),
                Err(error) => return Err(error.to_string()),
            };
            if let Some(archive) = archive {
                paths.push(archive_path(h).into());
                paths.push(archive_id_path(&archive.record.inputs.block_id).into());
                if let Some(group) = &archive.record.inputs.ordered_group {
                    paths.push(
                        archive_group_path(&group.root().map_err(|e| format!("{e:?}"))?).into(),
                    );
                }
            }
        }
        self.store
            .remove_cache_records(&paths)
            .map_err(|e| e.to_string())?;
        let pins = retained
            .iter()
            .flat_map(|h| h.to_be_bytes())
            .collect::<Vec<_>>();
        self.replace_records(vec![
            (cursor_path.into(), end.to_be_bytes().to_vec()),
            (pins_path.into(), pins),
        ])
    }
    pub(super) fn contains(&self, id: &str) -> bool {
        self.entries
            .iter()
            .flatten()
            .any(|entry| entry.block_id == id)
            || self
                .archive_locator(archive_id_path(id))
                .ok()
                .flatten()
                .is_some()
    }
    /// Bounded metadata lookup only. The caller must resolve the returned ID
    /// against the QC-selected candidate store before using its native VC.
    pub(super) fn try_group_candidates(
        &self,
        group: &EtdagDigest,
    ) -> Result<Vec<(u64, String)>, ProcessingProposalError> {
        self.try_group_candidates_at_or_below(group, u64::MAX)
    }
    /// Avoid decoding and verifying replay proofs that cannot yet satisfy the
    /// caller's locally verified finality fence. Returned proofs retain every
    /// existing integrity/authentication check; this bound grants no authority.
    pub(super) fn try_group_candidates_at_or_below(
        &self,
        group: &EtdagDigest,
        maximum_height: u64,
    ) -> Result<Vec<(u64, String)>, ProcessingProposalError> {
        let mut result = Vec::new();
        for (slot, entry) in self.entries.iter().enumerate() {
            let Some(entry) = entry else { continue };
            if entry.validation.is_none() || entry.height > maximum_height {
                continue;
            }
            let inputs = self.try_read(slot, entry)?;
            if inputs
                .ordered_group
                .as_ref()
                .is_some_and(|g| g.root().as_ref() == Ok(group))
            {
                result.push((entry.height, entry.block_id.clone()));
            }
        }
        if let Some(height) = self
            .archive_locator(archive_group_path(group))?
            .filter(|height| *height <= maximum_height)
        {
            let archive = self
                .try_read_archive_at(height)?
                .ok_or("processing group locator lacks archive")?;
            if !archive
                .record
                .inputs
                .ordered_group
                .as_ref()
                .is_some_and(|g| g.root().as_ref() == Ok(group))
            {
                return Err("processing group locator differs from archive".into());
            }
            result.push((height, archive.record.inputs.block_id.clone()));
        }
        result.sort();
        result.dedup();
        Ok(result)
    }
    pub(super) fn has_validation(&self, id: &str) -> bool {
        self.entries
            .iter()
            .flatten()
            .any(|entry| entry.block_id == id && entry.validation.is_some())
            || self
                .archive_locator(archive_id_path(id))
                .ok()
                .flatten()
                .is_some()
    }

    pub(crate) fn stage(
        &mut self,
        request: Arc<ProcessingBuildRequest>,
        candidate: Arc<BudgetedExecutionCandidate>,
        ordered_group: Option<&ProcessingOrderGroup>,
        publications: &[ProcessingReadyRecord],
    ) -> Result<DurableProcessingCandidate, String> {
        self.try_stage(request, candidate, ordered_group, publications)
            .map_err(|error| error.to_string())
    }
    pub(crate) fn try_stage(
        &mut self,
        request: Arc<ProcessingBuildRequest>,
        candidate: Arc<BudgetedExecutionCandidate>,
        ordered_group: Option<&ProcessingOrderGroup>,
        publications: &[ProcessingReadyRecord],
    ) -> Result<DurableProcessingCandidate, ProcessingProposalError> {
        candidate.validate()?;
        if !Arc::ptr_eq(candidate.state.budget(), &self.budget)
            || candidate.height != request.context.height
            || candidate.parent_block_id != request.parent.block_id()
        {
            return Err("processing staging differs from native assembly owner".into());
        }
        let CandidateProtectedMaterial::Processing(material) = &candidate.protected_material else {
            return Err("legacy candidate cannot enter processing staging".into());
        };
        if material.namespace_root != self.header.namespace
            || material.ordered_group
                != ordered_group
                    .map(ProcessingOrderGroup::commitment)
                    .transpose()
                    .map_err(|e| format!("processing group: {e:?}"))?
            || publications.len() > 4096
        {
            return Err("processing replay inputs differ from candidate commitments".into());
        }
        // Count borrowed inputs before cloning any member/publication graph.
        struct Counter(usize);
        impl std::io::Write for Counter {
            fn write(&mut self, bytes: &[u8]) -> std::io::Result<usize> {
                self.0 = self
                    .0
                    .checked_add(bytes.len())
                    .filter(|n| *n <= MAX_BYTES - 16 * 1024)
                    .ok_or_else(|| std::io::Error::other("processing proposal inputs too large"))?;
                Ok(bytes.len())
            }
            fn flush(&mut self) -> std::io::Result<()> {
                Ok(())
            }
        }
        let _measure = self
            .budget
            .reserve(16 * 1024)
            .map_err(ProcessingProposalError::from)?;
        let mut count = Counter(0);
        serde_json::to_writer(&mut count, &(ordered_group, publications))
            .map_err(|e| e.to_string())?;
        let _encode = self
            .budget
            .reserve(charge(count.0 + 16 * 1024)?)
            .map_err(ProcessingProposalError::from)?;
        let inputs = ProcessingProposalInputs {
            context: request.context.clone(),
            parent: request.parent.clone(),
            takeover_id: request.takeover.as_ref().map(|tc| tc.id().to_owned()),
            block_id: candidate.block_id.clone(),
            state_root: candidate.state_root.clone(),
            protected_execution_root: candidate.protected_execution_root.clone(),
            ordered_group: ordered_group.cloned(),
            publications: publications.to_vec(),
            certified_ancestors: Vec::new(),
        };
        let record = Record {
            version: 1,
            namespace: self.header.namespace.clone(),
            inputs,
        };
        check(&record, &self.header.namespace)?;
        let bytes = encode(&record)?;
        if bytes.len() > MAX_BYTES {
            return Err("processing proposal input encoding exceeds bound".into());
        }
        if let Some((slot, entry)) = self.entries.iter().enumerate().find_map(|(slot, entry)| {
            entry
                .as_ref()
                .filter(|entry| entry.block_id == candidate.block_id)
                .map(|entry| (slot, entry))
        }) {
            let restored = self.try_read(slot, entry)?;
            // Stable candidate identity may be re-enveloped in a later native round.
            if restored.ordered_group != record.inputs.ordered_group
                || restored.publications != record.inputs.publications
                || restored.state_root != candidate.state_root
                || restored.parent != request.parent
            {
                return Err("conflicting immutable processing replay inputs".into());
            }
        } else {
            let slot = self
                .entries
                .iter()
                .position(Option::is_none)
                .ok_or(ProcessingProposalError::StagingFull)?;
            let entry = Index {
                block_id: candidate.block_id.clone(),
                height: candidate.height,
                root: root(&bytes),
                bytes: bytes.len(),
                validation: None,
            };
            self.replace(slot, bytes)?;
            self.entries[slot] = Some(entry);
        }
        Ok(DurableProcessingCandidate { request, candidate })
    }
    fn read(&self, slot: usize, entry: &Index) -> Result<ChargedInputs, String> {
        self.try_read(slot, entry)
            .map_err(|error| error.to_string())
    }
    fn try_read(
        &self,
        slot: usize,
        entry: &Index,
    ) -> Result<ChargedInputs, ProcessingProposalError> {
        let _decode = self
            .budget
            .reserve(charge(entry.bytes)?)
            .map_err(ProcessingProposalError::from)?;
        let bytes = self
            .store
            .inspect_consistent(|reader| {
                reader
                    .with_maximum_bytes(entry.bytes)
                    .read_optional_bounded(path(slot))
            })
            .map_err(|e| e.to_string())?
            .map_err(|e| e.to_string())?
            .ok_or("missing processing replay inputs")?;
        if bytes.len() != entry.bytes || root(&bytes) != entry.root {
            return Err("immutable processing replay inputs changed".into());
        }
        let record: Record = serde_json::from_slice(&bytes).map_err(|e| e.to_string())?;
        check(&record, &self.header.namespace)?;
        Ok(ChargedInputs {
            inputs: record.inputs,
            _permit: _decode,
        })
    }
    pub(super) fn load_inputs(&self, block_id: &str) -> Result<ChargedInputs, String> {
        self.try_load_inputs(block_id)
            .map_err(|error| error.to_string())
    }
    pub(super) fn try_load_inputs(
        &self,
        block_id: &str,
    ) -> Result<ChargedInputs, ProcessingProposalError> {
        if !self
            .entries
            .iter()
            .flatten()
            .any(|entry| entry.block_id == block_id)
        {
            let archive = self
                .try_read_archive(block_id)?
                .ok_or("unknown processing replay inputs")?;
            return Ok(ChargedInputs {
                inputs: archive.record.inputs,
                _permit: archive._permit,
            });
        }
        let (slot, entry) = self
            .entries
            .iter()
            .enumerate()
            .find_map(|(slot, entry)| {
                entry
                    .as_ref()
                    .filter(|entry| entry.block_id == block_id)
                    .map(|entry| (slot, entry))
            })
            .ok_or("unknown processing replay inputs")?;
        self.try_read(slot, entry)
    }
    pub(crate) fn with_inputs<T>(
        &self,
        block_id: &str,
        action: impl FnOnce(&ProcessingProposalInputs) -> Result<T, String>,
    ) -> Result<T, String> {
        action(&self.load_inputs(block_id)?.inputs)
    }
    /// Capture exact native reveal authority per candidate before disclosing
    /// any share. Later round changes cannot erase an unfinished worker's VC.
    pub(crate) fn persist_validation(
        &mut self,
        block_id: &str,
        vc: &synergy_posy::ProposalValidationCertificate,
    ) -> Result<(), String> {
        self.try_persist_validation(block_id, vc)
            .map_err(|error| error.to_string())
    }
    pub(crate) fn try_persist_validation(
        &mut self,
        block_id: &str,
        vc: &synergy_posy::ProposalValidationCertificate,
    ) -> Result<(), ProcessingProposalError> {
        if !self
            .entries
            .iter()
            .flatten()
            .any(|entry| entry.block_id == block_id)
        {
            let archive = self
                .try_read_archive(block_id)?
                .ok_or("unknown processing VC subject")?;
            return verify_validation(&archive.record.inputs, vc, &self.authority)
                .map_err(ProcessingProposalError::from);
        }
        let (slot, entry) = self
            .entries
            .iter()
            .enumerate()
            .find_map(|(slot, entry)| {
                entry
                    .as_ref()
                    .filter(|entry| entry.block_id == block_id)
                    .map(|entry| (slot, entry))
            })
            .ok_or("unknown processing VC subject")?;
        let _measure = self
            .budget
            .reserve(16 * 1024)
            .map_err(ProcessingProposalError::from)?;
        let mut count = SizeCounter(0);
        serde_json::to_writer(&mut count, vc).map_err(|e| e.to_string())?;
        let _encode = self
            .budget
            .reserve(charge(count.0)?)
            .map_err(ProcessingProposalError::from)?;
        let inputs = self.try_read(slot, entry)?;
        verify_validation(&inputs, vc, &self.authority)?;
        if entry.validation.is_some() {
            self.try_with_validation(block_id, |_| Ok(()))?;
            return Ok(()); // Keep the first valid proof, including signer variants.
        }
        let bytes = encode(vc)?;
        let index = (root(&bytes), bytes.len());
        drop(inputs);
        self.replace_records(vec![(validation_path(slot), bytes)])?;
        self.entries[slot]
            .as_mut()
            .expect("occupied processing VC slot")
            .validation = Some(index);
        Ok(())
    }
    pub(crate) fn with_validation<T>(
        &self,
        block_id: &str,
        action: impl FnOnce(&synergy_posy::ProposalValidationCertificate) -> Result<T, String>,
    ) -> Result<T, String> {
        self.try_with_validation(block_id, |vc| {
            action(vc).map_err(ProcessingProposalError::from)
        })
        .map_err(|error| error.to_string())
    }
    pub(crate) fn try_with_validation<T>(
        &self,
        block_id: &str,
        action: impl FnOnce(
            &synergy_posy::ProposalValidationCertificate,
        ) -> Result<T, ProcessingProposalError>,
    ) -> Result<T, ProcessingProposalError> {
        #[cfg(feature = "qualification-timing")]
        let _diagnostic = diagnostic_span(DiagnosticStage::ValidationRead);
        if !self
            .entries
            .iter()
            .flatten()
            .any(|entry| entry.block_id == block_id)
        {
            let archive = self
                .try_read_archive(block_id)?
                .ok_or("unknown processing VC subject")?;
            return action(&archive.record.validation);
        }
        let (slot, entry) = self
            .entries
            .iter()
            .enumerate()
            .find_map(|(slot, entry)| {
                entry
                    .as_ref()
                    .filter(|entry| entry.block_id == block_id)
                    .map(|entry| (slot, entry))
            })
            .ok_or("unknown processing VC subject")?;
        let (expected, size) = entry
            .validation
            .as_ref()
            // A QC can arrive before this node durably publishes its ECHO
            // proof. Absence in the index is an unfinished prerequisite;
            // a missing/changed file for an indexed proof remains corruption.
            .ok_or(ProcessingProposalError::AwaitingValidation)?;
        let _decode = self
            .budget
            .reserve(charge(*size)?)
            .map_err(ProcessingProposalError::from)?;
        let bytes = self
            .store
            .inspect_consistent(|reader| {
                reader
                    .with_maximum_bytes(*size)
                    .read_optional_bounded(validation_path(slot))
            })
            .map_err(|e| e.to_string())?
            .map_err(|e| e.to_string())?
            .ok_or("missing durable processing VC")?;
        if bytes.len() != *size || root(&bytes) != *expected {
            return Err("immutable processing VC changed".into());
        }
        let vc: synergy_posy::ProposalValidationCertificate =
            serde_json::from_slice(&bytes).map_err(|e| e.to_string())?;
        let inputs = self.try_read(slot, entry)?;
        verify_validation(&inputs, &vc, &self.authority)?;
        action(&vc)
    }

    pub(crate) fn retire(
        &mut self,
        block_id: &str,
        verifier: &impl ProcessingProposalRetirement,
    ) -> Result<(), String> {
        let (slot, entry) = self
            .entries
            .iter()
            .enumerate()
            .find_map(|(slot, entry)| {
                entry
                    .as_ref()
                    .filter(|entry| entry.block_id == block_id)
                    .map(|entry| (slot, entry))
            })
            .ok_or("unknown processing retirement")?;
        self.read(slot, entry)?;
        if entry.validation.is_some() {
            self.with_validation(block_id, |_| Ok(()))?;
        }
        verifier.verify_retirement(entry.height, &entry.block_id)?;
        self.replace_records(vec![
            (path(slot), b"null".to_vec()),
            (validation_path(slot), b"null".to_vec()),
        ])?;
        self.entries[slot] = None;
        Ok(())
    }
    /// Transport only: exact bounded replay inputs plus the original native
    /// ECHO proof. The receiver must still regenerate the entire transition.
    pub(crate) fn export_sync(
        &self,
        block_id: &str,
    ) -> Result<(Vec<u8>, WorldResourcePermit), String> {
        self.try_export_sync(block_id)
            .map_err(|error| error.to_string())
    }
    pub(crate) fn try_export_sync(
        &self,
        block_id: &str,
    ) -> Result<(Vec<u8>, WorldResourcePermit), ProcessingProposalError> {
        let encode_export =
            |inputs: &ProcessingProposalInputs,
             vc: &synergy_posy::ProposalValidationCertificate| {
                let value = (1u32, inputs, vc);
                let mut size = SizeCounter(0);
                serde_json::to_writer(&mut size, &value).map_err(|e| e.to_string())?;
                let permit = self
                    .budget
                    .reserve(charge(size.0)?)
                    .map_err(ProcessingProposalError::from)?;
                Ok((encode(&value)?, permit))
            };
        if !self
            .entries
            .iter()
            .flatten()
            .any(|entry| entry.block_id == block_id)
        {
            // One charged, authenticated immutable archive owns both inputs
            // and VC. Keep its permit through encoding; loading each half
            // separately repeats the full QC/VC verification and allocation.
            let archive = self
                .try_read_archive(block_id)?
                .ok_or("unknown processing replay inputs")?;
            return encode_export(&archive.record.inputs, &archive.record.validation);
        }
        let inputs = self.try_load_inputs(block_id)?;
        self.try_with_validation(block_id, |vc| encode_export(&inputs, vc))
    }

    /// Store certified replay inputs, never a caller-provided World. Native
    /// execution replays these inputs before installing canonical state.
    pub(crate) fn import_sync(
        &mut self,
        bytes: &[u8],
        candidate: &BudgetedExecutionCandidate,
        qc: &synergy_posy::SimplifiedQuorumCertificate,
    ) -> Result<(), String> {
        if bytes.len() > MAX_BYTES {
            return Err("processing Sync proof exceeds bound".into());
        }
        let _decode = self
            .budget
            .reserve(charge(bytes.len())?)
            .map_err(|e| e.to_string())?;
        let (inputs, vc) = verify_checkpoint_replay(
            bytes,
            candidate,
            qc,
            &self.authority,
            &self.header.namespace,
        )?;
        self.try_archive_imported(inputs, vc, qc)
            .map_err(|error| error.to_string())
    }

    /// Offline checkpoint import preserves every live stage. A verified
    /// checkpoint is archived directly rather than evicting a pending input.
    pub(crate) fn import_checkpoint(
        &mut self,
        bytes: &[u8],
        candidate: &BudgetedExecutionCandidate,
        qc: &synergy_posy::SimplifiedQuorumCertificate,
    ) -> Result<(), String> {
        let _decode = self
            .budget
            .reserve(charge(bytes.len())?)
            .map_err(|e| e.to_string())?;
        let (inputs, vc) = verify_checkpoint_replay(
            bytes,
            candidate,
            qc,
            &self.authority,
            &self.header.namespace,
        )?;
        self.try_archive_imported(inputs, vc, qc)
            .map_err(|error| error.to_string())
    }

    pub(crate) fn try_import_certified(
        &mut self,
        bytes: &[u8],
        qc: &synergy_posy::SimplifiedQuorumCertificate,
    ) -> Result<(), ProcessingProposalError> {
        if bytes.len() > MAX_BYTES {
            return Err("processing ancestor proof exceeds bound".into());
        }
        let _decode = self
            .budget
            .reserve(charge(bytes.len())?)
            .map_err(ProcessingProposalError::from)?;
        let (version, inputs, vc): (
            u32,
            ProcessingProposalInputs,
            synergy_posy::ProposalValidationCertificate,
        ) = serde_json::from_slice(bytes).map_err(|e| e.to_string())?;
        qc.verify(
            &self.authority.epoch,
            &self.authority.registry,
            self.authority.as_ref(),
        )
        .map_err(|e| e.to_string())?;
        inputs
            .context
            .validate_against(&self.authority.epoch)
            .map_err(|e| e.to_string())?;
        if version != 1
            || inputs.context.height != qc.context.height
            || inputs.block_id != qc.block_id
            || inputs.parent != qc.parent
            || inputs.protected_execution_root != qc.protected_execution_root
        {
            return Err("processing ancestor differs from native QC".into());
        }
        verify_validation(&inputs, &vc, &self.authority)?;
        verify_certified_subject(&vc, qc)?;
        self.try_archive_imported(inputs, vc, qc)
    }

    /// Certified transport inputs are not speculative proposals. Preserve the
    /// authenticated inputs, VC and QC in the existing archive even when a
    /// missing predecessor delays replay. Never consume or evict pre-QC slots.
    fn try_archive_imported(
        &mut self,
        inputs: ProcessingProposalInputs,
        vc: synergy_posy::ProposalValidationCertificate,
        qc: &synergy_posy::SimplifiedQuorumCertificate,
    ) -> Result<(), ProcessingProposalError> {
        if !inputs.certified_ancestors.is_empty() {
            return Err("nested processing ancestor proofs are forbidden".into());
        }
        check_inputs(&inputs, &self.header.namespace)?;
        // Every entry point verifies the selected network, signatures and exact
        // stable subject before reaching this private durable-write helper.
        if self.contains(&inputs.block_id) {
            let old = self.try_load_inputs(&inputs.block_id)?;
            if old.parent != inputs.parent
                || old.state_root != inputs.state_root
                || old.ordered_group != inputs.ordered_group
                || old.publications != inputs.publications
            {
                return Err("processing Sync conflicts with original replay inputs".into());
            }
        }
        if let Some(old) = self.try_read_archive_at(inputs.context.height)? {
            if old.record.inputs.block_id != inputs.block_id
                || old.record.inputs.state_root != inputs.state_root
            {
                return Err("conflicting immutable certified processing archive".into());
            }
            return Ok(());
        }
        let value = CertifiedArchiveRef {
            version: 1,
            namespace: &self.header.namespace,
            inputs: &inputs,
            validation: &vc,
            qc,
        };
        let mut size = SizeCounter(0);
        serde_json::to_writer(&mut size, &value).map_err(|e| e.to_string())?;
        if size.0 > MAX_BYTES {
            return Err("processing Sync durable records exceed bound".into());
        }
        let _encode = self.budget.reserve(charge(size.0)?)?;
        let mut writes = vec![
            (archive_path(inputs.context.height), encode(&value)?),
            (
                archive_id_path(&inputs.block_id),
                inputs.context.height.to_be_bytes().to_vec(),
            ),
        ];
        if let Some(group) = &inputs.ordered_group {
            writes.push((
                archive_group_path(&group.root().map_err(|e| format!("{e:?}"))?),
                inputs.context.height.to_be_bytes().to_vec(),
            ));
        }
        self.replace_records(writes)
            .map_err(ProcessingProposalError::from)
    }
    fn replace(&mut self, slot: usize, bytes: Vec<u8>) -> Result<(), String> {
        self.replace_records(vec![(path(slot), bytes)])
    }
    fn replace_records(&mut self, writes: Vec<(String, Vec<u8>)>) -> Result<(), String> {
        let mut next = self.header.clone();
        next.generation = next
            .generation
            .checked_add(1)
            .ok_or("processing proposal generation overflow")?;
        let mut transaction =
            StorageTransaction::new(MAX_BYTES + 4096).map_err(|e| e.to_string())?;
        for (path, bytes) in writes {
            transaction.put(path, bytes).map_err(|e| e.to_string())?;
        }
        transaction
            .put(HEADER, encode(&next)?)
            .map_err(|e| e.to_string())?;
        transaction
            .commit_guarded(
                &mut self.store,
                &[StoragePrecondition {
                    relative_path: HEADER.into(),
                    required: RequiredRecord::Exact(encode(&self.header)?),
                }],
            )
            .map_err(|e| e.to_string())?;
        self.header = next;
        Ok(())
    }
}

/// Pure checkpoint admission: the existing native Sync candidate/QC/ECHO checks,
/// without opening or modifying a processing journal. It certifies a checkpoint;
/// it does not claim local deterministic replay of the skipped transitions.
pub(crate) fn verify_checkpoint_replay(
    bytes: &[u8],
    candidate: &BudgetedExecutionCandidate,
    qc: &synergy_posy::SimplifiedQuorumCertificate,
    authority: &VerifiedAuthority,
    namespace: &EtdagDigest,
) -> Result<
    (
        ProcessingProposalInputs,
        synergy_posy::ProposalValidationCertificate,
    ),
    String,
> {
    if bytes.len() > MAX_BYTES {
        return Err("processing Sync proof exceeds bound".into());
    }
    let (version, inputs, vc): (
        u32,
        ProcessingProposalInputs,
        synergy_posy::ProposalValidationCertificate,
    ) = serde_json::from_slice(bytes).map_err(|e| e.to_string())?;
    qc.verify(&authority.epoch, &authority.registry, authority)
        .map_err(|e| e.to_string())?;
    candidate.validate()?;
    inputs
        .context
        .validate_against(&authority.epoch)
        .map_err(|e| e.to_string())?;
    let CandidateProtectedMaterial::Processing(material) = &candidate.protected_material else {
        return Err("processing Sync proof accompanies legacy candidate".into());
    };
    if version != 1
        || candidate.height != qc.context.height
        || candidate.block_id != qc.block_id
        || candidate.protected_execution_root != qc.protected_execution_root
        || candidate.parent_block_id != qc.parent_block_id
        || inputs.parent != qc.parent
        || inputs.context.height != candidate.height
        || inputs.block_id != candidate.block_id
        || inputs.state_root != candidate.state_root
        || inputs.protected_execution_root != candidate.protected_execution_root
        || material.namespace_root != *namespace
        || material.ordered_group
            != inputs
                .ordered_group
                .as_ref()
                .map(ProcessingOrderGroup::commitment)
                .transpose()
                .map_err(|e| format!("{e:?}"))?
    {
        return Err("processing Sync replay differs from certified subject".into());
    }
    check_inputs(&inputs, namespace)?;
    if !inputs.certified_ancestors.is_empty() {
        return Err("nested processing ancestor proofs are forbidden".into());
    }
    verify_validation(&inputs, &vc, authority)?;
    verify_certified_subject(&vc, qc)?;
    Ok((inputs, vc))
}

/// Replay inputs retain the first observed proposal envelope. A valid QC may
/// arrive from an earlier round for that same immutable candidate. Proof rounds
/// are independently verified by native PoSy; they do not order replay records.
/// Require exact equality of the complete stable signed subject instead.
fn verify_certified_subject(
    vc: &synergy_posy::ProposalValidationCertificate,
    qc: &synergy_posy::SimplifiedQuorumCertificate,
) -> Result<(), String> {
    if vc.candidate != qc.subject().map_err(|error| error.to_string())? {
        return Err("processing VC and QC certify different stable subjects".into());
    }
    Ok(())
}

fn verify_validation(
    inputs: &ProcessingProposalInputs,
    vc: &synergy_posy::ProposalValidationCertificate,
    authority: &VerifiedAuthority,
) -> Result<(), String> {
    vc.verify(&authority.epoch, &authority.registry, authority)
        .map_err(|e| e.to_string())?;
    let mut context = inputs.context.clone();
    context.round = 0;
    if vc.candidate.context != context
        || vc.candidate.block_id != inputs.block_id
        || vc.candidate.parent_block_id != inputs.parent.block_id()
        || vc.candidate.parent != inputs.parent
        || vc.candidate.protected_execution_root != inputs.protected_execution_root
    {
        return Err("processing VC differs from immutable replay subject".into());
    }
    Ok(())
}

struct SizeCounter(usize);
impl std::io::Write for SizeCounter {
    fn write(&mut self, bytes: &[u8]) -> std::io::Result<usize> {
        self.0 = self
            .0
            .checked_add(bytes.len())
            .filter(|size| *size <= MAX_BYTES)
            .ok_or_else(|| std::io::Error::other("processing VC encoding exceeds bound"))?;
        Ok(bytes.len())
    }
    fn flush(&mut self) -> std::io::Result<()> {
        Ok(())
    }
}
